const allowedOrigins=(process.env.ALLOWED_ORIGINS||'http://localhost:5173,http://localhost:5174').split(',').map(v=>v.trim()).filter(Boolean);
await app.register(cors,{origin:(origin,cb)=>{if(!origin||allowedOrigins.includes(origin))return cb(null,true);return cb(new Error('Origin not allowed by FairShift CORS policy'),false)},credentials:true});
