const hashPassword=(password:string,salt:string)=>scryptSync(password,salt,64).toString('hex');
const safeEqual=(a:string,b:string)=>{const aa=Buffer.from(a);const bb=Buffer.from(b);return aa.length===bb.length&&timingSafeEqual(aa,bb)};
const tokenHash=(token:string)=>createHash('sha256').update(token).digest('hex');
const publicPaths=new Set(['/api/health','/api/auth/login','/api/auth/register-device']);
function getOrgSigningKeys(){
 let privatePem=setting('org_signing_private_pem','');let publicPem=setting('org_signing_public_pem','');
 if(!privatePem||!publicPem){const pair=generateKeyPairSync('ec',{namedCurve:'prime256v1'});privatePem=pair.privateKey.export({type:'pkcs8',format:'pem'}).toString();publicPem=pair.publicKey.export({type:'spki',format:'pem'}).toString();setSetting('org_signing_private_pem',privatePem);setSetting('org_signing_public_pem',publicPem);setSetting('org_signing_mode','demo-generated-key-in-local-database');}
 return {privateKey:createPrivateKey(privatePem),publicKey:createPublicKey(publicPem)};
}
const orgSigningKeys=getOrgSigningKeys();
app.addHook('preHandler',async(request,reply)=>{
  if(process.env.DEMO_MODE!=='0') return;
  const path=request.url.split('?')[0];
  if(publicPaths.has(path)||path.startsWith('/api/verify/')||path.startsWith('/api/skills/')&&path.endsWith('/verify')) return;
  const auth=request.headers.authorization||''; const token=auth.startsWith('Bearer ')?auth.slice(7):'';
  if(!token) return reply.code(401).send({error:'Authentication required. Sign in to FairShift first.'});
  const session=db.prepare('SELECT u.id,u.org_id,u.site_id,u.role,u.display_name,u.language,s.expires_at FROM auth_sessions s JOIN users u ON u.id=s.user_id WHERE s.token_hash=?').get(tokenHash(token)) as any;
  if(!session||new Date(session.expires_at).getTime()<Date.now()) return reply.code(401).send({error:'Session expired or invalid.'});
  (request as any).fairshiftUser=session;
  const role=session.role as string;
  const employerRoles=['supervisor','manager','owner','auditor'];
  if(path.startsWith('/api/admin')||path.startsWith('/api/compliance')||path.startsWith('/api/rules')||path.startsWith('/api/rule-watcher')||path.startsWith('/api/contractors')||path.startsWith('/api/certifications')||path.startsWith('/api/export')||path.startsWith('/api/ledger')||path.startsWith('/api/sector-pack')||path.startsWith('/api/roster')||path.startsWith('/api/briefing')||path.startsWith('/api/insights')||path==='/api/forecast'||path==='/api/fairness'||path==='/api/impact'||path==='/api/feedback/aggregate'||path==='/api/agents/runs'||path==='/api/agents/prompts') {
    if(!employerRoles.includes(role)) return reply.code(403).send({error:'This action requires an employer or auditor role.'});
  }
  if((request.method==='PATCH'&&(path.startsWith('/api/reports/')||path.startsWith('/api/disputes/')||path.startsWith('/api/swaps/')||path.startsWith('/api/sos/')||path.startsWith('/api/cases/'))) || (request.method==='GET'&&path==='/api/disputes') || path==='/api/tickets' || path==='/api/cases') {
    if(!employerRoles.includes(role)) return reply.code(403).send({error:'This action requires an employer or auditor role.'});
  }
  if(path==='/api/reset'||path==='/api/ledger/tamper-test'||path.startsWith('/api/demo/scenario/')) {
    if(!['owner','manager'].includes(role)) return reply.code(403).send({error:'Demo control requires owner or manager role.'});
  }
});

const packs:any={construction:{id:'construction-v0.1',name:'Construction',roles:['Site worker','Supervisor','Site manager'],hazards:['Wet floor','Electrical hazard','Fire','Heat exposure','Equipment','PPE concern'],payModel:'daily',checkIn:'Gate QR'},college:{id:'college-v0.1',name:'College campus',roles:['Housekeeping','Security','Maintenance','Mess staff'],hazards:['Wet floor','Electrical hazard','Fire','Equipment','Harassment','PPE concern'],payModel:'monthly',checkIn:'QR / supervisor'},hospital:{id:'hospital-draft-v0.1',name:'Hospital · generated draft',roles:['Nursing','Sanitation','Security','Facilities'],hazards:['Wet floor','Biological safety','Needlestick','Equipment','Fatigue','Harassment'],payModel:'monthly',checkIn:'QR / supervisor',simulated:true}};
const clean=(v:string)=>v.replace(/[<>\u0000-\u001f]/g,'').trim().slice(0,2000);
const site=()=>setting('sector','construction')==='college'?'SITE-COL-A':'SITE-CON-B';
app.get('/api/health',async()=>({ok:true,service:'FairShift API',mode:process.env.AI_MODE||'mock',database:'sqlite',demo:true}));
app.post('/api/auth/login',async(req,reply)=>{
 const p=z.object({identifier:z.string().min(2).max(200),password:z.string().min(4).max(200).optional(),pin:z.string().min(4).max(12).optional()}).refine(v=>Boolean(v.password||v.pin)).safeParse(req.body);
 if(!p.success)return reply.code(400).send({error:'Provide your phone/email and password or PIN.'});
 const user=db.prepare('SELECT * FROM users WHERE phone=? OR email=?').get(p.data.identifier,p.data.identifier) as any;
 if(!user)return reply.code(401).send({error:'Invalid credentials.'});
 const supplied=p.data.password?hashPassword(p.data.password,user.id):p.data.pin?hashPassword(p.data.pin,user.id):'';
 const expected=p.data.password?user.password_hash:user.pin_hash;
 if(!expected||!safeEqual(supplied,expected))return reply.code(401).send({error:'Invalid credentials.'});
 const token=randomBytes(32).toString('base64url');const expires=new Date(Date.now()+8*60*60*1000).toISOString();
 db.prepare('INSERT INTO auth_sessions(token_hash,user_id,expires_at,created_at) VALUES(?,?,?,?)').run(tokenHash(token),user.id,expires,now());
 return {ok:true,token,expiresAt:expires,user:{id:user.id,name:user.display_name,role:user.role,siteId:user.site_id,language:user.language},demo:process.env.DEMO_MODE!=='0'};
});
app.post('/api/auth/logout',async(req,reply)=>{const token=(req.headers.authorization||'').replace(/^Bearer /,'');if(token)db.prepare('DELETE FROM auth_sessions WHERE token_hash=?').run(tokenHash(token));return {ok:true}});
app.get('/api/auth/me',async(req,reply)=>{const token=(req.headers.authorization||'').replace(/^Bearer /,'');const user=db.prepare('SELECT u.id,u.display_name,u.role,u.site_id,u.language,s.expires_at FROM auth_sessions s JOIN users u ON u.id=s.user_id WHERE s.token_hash=?').get(tokenHash(token));if(!user)return reply.code(401).send({error:'Invalid session'});return {user}});
app.post('/api/auth/register-device',async(req,reply)=>{const p=z.object({workerId:z.string().min(2).max(50),publicKey:z.string().min(40).max(5000)}).safeParse(req.body);if(!p.success)return reply.code(400).send({error:'Invalid device public key'});try{createPublicKey({key:Buffer.from(p.data.publicKey,'base64'),format:'der',type:'spki'});}catch{return reply.code(400).send({error:'Public key must be a valid SPKI key'});}db.prepare('INSERT INTO device_keys(worker_id,public_key,created_at) VALUES(?,?,?) ON CONFLICT(worker_id) DO UPDATE SET public_key=excluded.public_key,created_at=excluded.created_at').run(p.data.workerId,p.data.publicKey,now());return {ok:true,workerId:p.data.workerId,algorithm:'ECDSA P-256',storage:'Server stores the public key only.'}});

app.get('/api/worker/home',async(req)=>{const q=z.object({reporterToken:z.string().min(16).max(128).optional()}).safeParse(req.query);let ownReports:any[]=[];if(q.success&&q.data.reporterToken){const epoch=Math.floor(Date.now()/(14*24*60*60*1000));const pseudonym=createHmac('sha256',process.env.SERVER_SECRET||'fairshift-demo-only').update(`${q.data.reporterToken}|${site()}|${epoch}`).digest('hex');ownReports=db.prepare('SELECT id,category,severity,zone,summary,status,created_at FROM reports WHERE site_id=? AND pseudonym=? ORDER BY id DESC LIMIT 20').all(site(),pseudonym)}const receipts=db.prepare('SELECT id,type,method,created_at,signature_status,hash FROM receipts WHERE worker_id=? ORDER BY id DESC LIMIT 10').all('W-101');const reports=ownReports;const latest=db.prepare('SELECT * FROM payslips WHERE worker_id=? ORDER BY id DESC LIMIT 1').get('W-101') as any;const notices=db.prepare('SELECT id,title,body,created_at,simulated FROM notices ORDER BY id DESC LIMIT 5').all();const collectiveCases=db.prepare("SELECT id,category,report_count,distinct_reporters,status,created_at FROM cases WHERE site_id=? AND status!='Resolved' ORDER BY id DESC LIMIT 5").all(site());const mySwaps=db.prepare('SELECT * FROM swaps WHERE worker_id=? ORDER BY id DESC LIMIT 5').all('W-101');const skills=db.prepare('SELECT id,name,issuer,issued_at,expires_at FROM skills WHERE worker_id=?').all('W-101');return {worker:{name:'Kavitha R.',site:setting('sector','construction')==='college'?'Greenfield College of Engineering':'Metro Rail Block B',language:'Tamil',sector:setting('sector','construction')},receipts,reports,collectiveCases,fatigue:38,pay:latest?{base:latest.base,overtime:latest.overtime_amount,deductions:latest.deductions,expectedNet:latest.base+latest.overtime_amount-latest.deductions,paidAmount:latest.paid_amount,period:latest.period}:{base:16000,overtime:2400,deductions:0,expectedNet:18400,paidAmount:17200,period:'Oct 2026'},notices,swaps:mySwaps,skills,disclaimer:'Synthetic demo data. Rule pack unverified.'}});
const checkSchema=z.object({type:z.enum(['in','out']),method:z.enum(['qr','geo','manual']).default('qr')});
app.post('/api/checkin',async(req,reply)=>{
 const schema=checkSchema.extend({workerId:z.string().min(2).max(50).default('W-101'),deviceTs:z.string().datetime().optional(),nonce:z.string().min(12).max(200).optional(),deviceSignature:z.string().min(80).max(200).optional(),coarseGeo:z.string().max(100).optional()});
 const p=schema.safeParse(req.body);if(!p.success)return reply.code(400).send({error:'Invalid check-in payload'});
 const worker=p.data.workerId;const last=db.prepare('SELECT id,type,hash FROM receipts WHERE worker_id=? ORDER BY id DESC LIMIT 1').get(worker) as any;
 if(last?.type===p.data.type)return reply.code(409).send({error:`Already checked ${p.data.type==='in'?'in':'out'}; alternate in/out event required.`});
 let deviceSig:string|null=null;let nonce:string|null=null;let status='Simulated — demo receipt';
 if(p.data.deviceSignature&&p.data.nonce&&p.data.deviceTs){
   const key=db.prepare('SELECT public_key FROM device_keys WHERE worker_id=?').get(worker) as any;
   if(!key)return reply.code(400).send({error:'No registered device key for this worker.'});
   if(db.prepare('SELECT nonce FROM used_nonces WHERE nonce=?').get(p.data.nonce))return reply.code(409).send({error:'Nonce replay detected.'});
   const payload={v:1,workerId:worker,siteId:site(),type:p.data.type,deviceTs:p.data.deviceTs,method:p.data.method,nonce:p.data.nonce,prevReceiptHash:last?.hash||null};
   try{const pub=createPublicKey({key:Buffer.from(key.public_key,'base64'),format:'der',type:'spki'});const valid=cryptoVerify('sha256',Buffer.from(canonicalJson(payload)),{key:pub,dsaEncoding:'ieee-p1363'},Buffer.from(p.data.deviceSignature,'base64url'));if(!valid)return reply.code(400).send({error:'Device signature verification failed.'});}catch{return reply.code(400).send({error:'Could not verify device signature.'});}
   nonce=p.data.nonce;deviceSig=p.data.deviceSignature;status='Device signature verified';db.prepare('INSERT INTO used_nonces(nonce,worker_id,used_at) VALUES(?,?,?)').run(nonce,worker,now());
 }
 const ts=now();const info=db.prepare('INSERT INTO receipts(worker_id,site_id,type,method,created_at,signature_status,nonce,device_sig,prev_hash,coarse_geo) VALUES(?,?,?,?,?,?,?,?,?,?)').run(worker,site(),p.data.type,p.data.method,ts,status,nonce,deviceSig,last?.hash||null,p.data.coarseGeo||null);const id=Number(info.lastInsertRowid);
 const receiptPayload={id,worker,site:site(),type:p.data.type,method:p.data.method,createdAt:ts,nonce,deviceSignature:deviceSig,prevHash:last?.hash||null};const serverSignature=cryptoSign('sha256',Buffer.from(canonicalJson(receiptPayload)),{key:orgSigningKeys.privateKey,dsaEncoding:'ieee-p1363'}).toString('base64url');const hash=addLedger('receipt',String(id),canonicalJson({...receiptPayload,serverSignature}));
 db.prepare('UPDATE receipts SET hash=?,server_sig=? WHERE id=?').run(hash,serverSignature,id);
 return {ok:true,id,type:p.data.type,method:p.data.method,signatureStatus:status,serverSignature,organizationPublicKey:orgSigningKeys.publicKey.export({type:'spki',format:'pem'}).toString(),hash,message:`Checked ${p.data.type==='in'?'in':'out'}. ${status}. Organization countersignature added.`,verificationUrl:`/api/verify/${id}`,previousReceiptHash:last?.hash||null,mode:deviceSig?'Device + organization signed':'Organization countersigned; device signature simulated'};
});

const reportSchema=z.object({category:z.string().min(2).max(60),zone:z.string().min(1).max(80),text:z.string().max(2000).optional().default(''),language:z.enum(['English','Tamil','Hindi','Telugu']).default('English'),reporterToken:z.string().min(16).max(128).optional()});
app.post('/api/reports',async(req,reply)=>{
 const p=reportSchema.safeParse(req.body);if(!p.success)return reply.code(400).send({error:'Please check the report fields.'});
 const {category,zone}=p.data;const severity=/electric|fire|harass|biological|needle|sos/i.test(category)?5:/wet floor|heat|equipment/i.test(category)?4:3;
 const summary=clean(p.data.text||`${category} reported in ${zone}`).slice(0,240);const epoch=Math.floor(Date.now()/(14*24*60*60*1000));const reporterMaterial=p.data.reporterToken||randomUUID();const pseudonym=createHmac('sha256',process.env.SERVER_SECRET||'fairshift-demo-only').update(`${reporterMaterial}|${site()}|${epoch}`).digest('hex');
 const result=db.prepare('INSERT INTO reports(site_id,category,severity,zone,summary,status,pseudonym,created_at,language) VALUES(?,?,?,?,?,?,?,?,?)').run(site(),category,severity,zone,summary,'Open',pseudonym,now(),p.data.language);const id=Number(result.lastInsertRowid);addLedger('report',String(id),canonicalJson({category,severity,zone,summary,language:p.data.language}));db.prepare('INSERT INTO tickets(report_id,status,updated_at) VALUES(?,?,?)').run(id,'Received',now());
 const prior=db.prepare("SELECT id,category,zone,summary,pseudonym,created_at FROM reports WHERE site_id=? AND id!=? AND created_at>=datetime('now','-14 days')").all(site(),id) as any[];
 const tokens=(v:string)=>new Set(v.toLowerCase().replace(/[^a-z0-9\s]/g,' ').split(/\s+/).filter((t:string)=>t.length>2));
 const candidates=prior.filter(r=>{if(r.category.toLowerCase()!==category.toLowerCase())return false;if(r.zone.toLowerCase()===zone.toLowerCase())return true;const a=tokens(summary),b=tokens(r.summary);const overlap=[...a].filter(t=>b.has(t)).length;return overlap/Math.max(1,new Set([...a,...b]).size)>=0.25});
 const distinct=new Set([...candidates.map(r=>r.pseudonym),pseudonym]);const days=new Set([...candidates.map(r=>String(r.created_at).slice(0,10)),now().slice(0,10)]);
 let casePromoted=false;let caseId:number|undefined;
 if(distinct.size>=3&&days.size>=2){const existing=db.prepare("SELECT id,report_count,distinct_reporters,severity FROM cases WHERE site_id=? AND category=? AND status!='Resolved' ORDER BY id DESC LIMIT 1").get(site(),category) as any;
   if(existing){caseId=existing.id;db.prepare('UPDATE cases SET report_count=?,distinct_reporters=?,severity=?,summary=? WHERE id=?').run(candidates.length+1,distinct.size,Math.min(5,Math.max(existing.severity,severity)+1),`Collective case: ${category} reported across ${days.size} days`,existing.id)}
   else{const c=db.prepare('INSERT INTO cases(site_id,category,summary,severity,report_count,distinct_reporters,status,created_at) VALUES(?,?,?,?,?,?,?,?)').run(site(),category,`Collective case: ${category} reported across ${days.size} days`,Math.min(5,severity+1),candidates.length+1,distinct.size,'Open',now());caseId=Number(c.lastInsertRowid)}
   db.prepare('UPDATE reports SET cluster_id=? WHERE id IN ('+[id,...candidates.map(r=>r.id)].join(',')+')').run(caseId);addLedger('collective-case',String(caseId),JSON.stringify({category,reportCount:distinct.size,distinctReporters:distinct.size,days:days.size}));casePromoted=true;
 }
 return {ok:true,id,severity,status:'Open',casePromoted,caseId,message:casePromoted?'Report received and grouped into a Collective Case.':'Report received. Your name is not shown to the admin interface.',privacy:'Pseudonym is never returned by this API. Pseudonyms are HMAC-derived for a site/14-day epoch; perfect anonymity is not guaranteed.'};
});

app.get('/api/verify/:id',async(req,reply)=>{const p=z.object({id:z.coerce.number().int().positive()}).safeParse(req.params);if(!p.success)return reply.code(400).send({valid:false,error:'Invalid receipt id'});const r=db.prepare('SELECT id,site_id,type,method,created_at,signature_status,hash,nonce,device_sig,server_sig,prev_hash FROM receipts WHERE id=?').get(p.data.id) as any;if(!r)return reply.code(404).send({valid:false,error:'Receipt not found'});const payload={id:r.id,worker:(db.prepare('SELECT worker_id FROM receipts WHERE id=?').get(r.id) as any).worker_id,site:r.site_id,type:r.type,method:r.method,createdAt:r.created_at,nonce:r.nonce,deviceSignature:r.device_sig,prevHash:r.prev_hash||null};let signatureValid=false;try{signatureValid=Boolean(r.server_sig)&&cryptoVerify('sha256',Buffer.from(canonicalJson(payload)),{key:orgSigningKeys.publicKey,dsaEncoding:'ieee-p1363'},Buffer.from(r.server_sig,'base64url'));}catch{}return {valid:signatureValid&&Boolean(r.hash),signatureValid,receipt:{id:r.id,site:r.site_id,type:r.type,method:r.method,time:r.created_at,hash:r.hash,signatureStatus:r.signature_status},organizationPublicKey:orgSigningKeys.publicKey.export({type:'spki',format:'pem'}).toString(),privacy:'Worker identity is not included in this public verification response.',mode:'Organization countersignature is verified; device signature is verified only when the check-in was submitted with a registered device key.'}});
app.get('/api/tickets',async()=>db.prepare('SELECT t.id,t.report_id,t.status,t.assignee,t.updated_at,r.category,r.severity,r.zone,r.summary FROM tickets t JOIN reports r ON r.id=t.report_id ORDER BY t.id DESC').all());
app.post('/api/rights/answer',async(req,reply)=>{const p=z.object({question:z.string().min(2).max(500)}).safeParse(req.body);if(!p.success)return reply.code(400).send({error:'Enter a question'});const q=p.data.question.toLowerCase();let answer='The active demo pack does not contain enough verified information to answer that question. Please consult the official notification or a qualified adviser.';if(q.includes('overtime'))answer=`The current demo pack uses an illustrative overtime multiplier of 2.0 and a weekly standard of 48 hours. These values are unverified demo defaults, not legal advice. Pack: ${setting('packVersion','demo-v0.1')}.`;else if(q.includes('break')||q.includes('rest'))answer='The demo workplace policy suggests 11 hours of rest between shifts. This is a configurable policy value, not a statement of law.';else if(q.includes('report')||q.includes('complaint'))answer='You can file a hazard report from the worker app. The demo stores a pseudonym for grouping; perfect anonymity is not guaranteed.';return {answer,source:`Active pack ${setting('packVersion','demo-v0.1')}`,mode:'Mock',disclaimer:'Decision support only; not legal advice.'}});
app.get('/api/skills/:id/verify',async(req,reply)=>{const p=z.object({id:z.coerce.number().int().positive()}).safeParse(req.params);if(!p.success)return reply.code(400).send({valid:false});const s=db.prepare('SELECT id,name,issuer,issued_at,signature FROM skills WHERE id=?').get(p.data.id) as any;if(!s)return reply.code(404).send({valid:false,error:'Credential not found'});const expected=createHash('sha256').update(`${s.name}|${s.issuer}|fairshift-demo`).digest('hex');return {valid:s.signature===expected,credential:{id:s.id,name:s.name,issuer:s.issuer,issuedAt:s.issued_at},disclaimer:'Demo signature only; not an accredited qualification.'}});
app.get('/api/admin/dashboard',async()=>{const reports=db.prepare('SELECT id,category,severity,zone,summary,status,created_at FROM reports WHERE site_id=? ORDER BY CASE status WHEN \'Open\' THEN 0 WHEN \'Seen\' THEN 1 ELSE 2 END,severity DESC,id DESC').all(site()) as any[];const receipts=db.prepare('SELECT COUNT(*) n FROM receipts').get() as any;const today=db.prepare("SELECT COUNT(DISTINCT worker_id) n FROM receipts WHERE type='in' AND date(created_at)=date('now')").get() as any;const open=reports.filter(r=>r.status!=='Resolved').length;const overdue=reports.filter(r=>r.status==='Open'&&r.severity>=4).length;const sector=setting('sector','construction');const feedbackCount=db.prepare('SELECT COUNT(*) n FROM feedback WHERE site_id=?').get(site()) as any;const cases=db.prepare('SELECT id,category,summary,severity,report_count,distinct_reporters,status,created_at FROM cases ORDER BY id DESC').all();const contractors=db.prepare('SELECT * FROM contractors').all();const certs=db.prepare("SELECT * FROM certifications WHERE date(expires_at)<=date('now','+14 days')").all();const sos=db.prepare("SELECT * FROM sos_events WHERE status='Active' ORDER BY id DESC").all();const swaps=db.prepare("SELECT * FROM swaps WHERE status='Pending' ORDER BY id DESC").all();return {stats:{workers:sector==='college'?30:40,activeShifts:Math.max(18,today.n||28),openReports:open,overdue,fairness:Math.max(60,86-open),overtime:86},reports,teams:[{name:'Outdoor crew',size:12,fatigue:'amber'},{name:'Night team',size:8,fatigue:'red'}],recent:[],sector,pack:packs[sector],receiptCount:receipts.n,updatedAt:now(),cases,contractors,certifications:certs,sos,swaps,feedbackCount:feedbackCount.n,disclaimer:'Synthetic demo data; rule pack is unverified.'}});
const statusSchema=z.object({status:z.enum(['Open','Seen','In progress','Resolved'])});
app.patch('/api/reports/:id/status',async(req,reply)=>{const p=z.object({id:z.coerce.number().int().positive()}).safeParse(req.params);const b=statusSchema.safeParse(req.body);if(!p.success||!b.success)return reply.code(400).send({error:'Invalid report or status'});const exists=db.prepare('SELECT id FROM reports WHERE id=?').get(p.data.id);if(!exists)return reply.code(404).send({error:'Report not found'});db.prepare('UPDATE reports SET status=? WHERE id=?').run(b.data.status,p.data.id);db.prepare('UPDATE tickets SET status=?,updated_at=? WHERE report_id=?').run(b.data.status,now(),p.data.id);addLedger('report-status',String(p.data.id),b.data.status);return {ok:true,id:p.data.id,status:b.data.status}});
app.post('/api/sector-pack',async(req,reply)=>{const p=z.object({sector:z.enum(['construction','college','hospital'])}).safeParse(req.body);if(!p.success)return reply.code(400).send({error:'Unknown sector pack'});if(p.data.sector==='hospital'){const pack={...packs.hospital,id:'hospital-draft-'+Date.now(),verified:false,needsHumanReview:true,source:'Mock Pack Generator',status:'draft'};const r=db.prepare('INSERT INTO rule_packs(sector,version,status,verified,as_of,json,source,created_at) VALUES(?,?,?,?,?,?,?,?)').run('hospital',pack.id,'draft',0,now().slice(0,10),JSON.stringify(pack),pack.source,now());addLedger('sector-pack-draft',String(r.lastInsertRowid),JSON.stringify(pack));return {ok:true,id:Number(r.lastInsertRowid),pack,status:'Draft created; current active sector unchanged until human approval',simulated:true}}setSetting('sector',p.data.sector);setSetting('packVersion',packs[p.data.sector].id);addLedger('sector-pack',p.data.sector,packs[p.data.sector].id);return {ok:true,pack:packs[p.data.sector],status:'Active demo pack'}});
app.post('/api/sector-pack/:id/approve',async(req,reply)=>{const p=z.object({id:z.coerce.number().int().positive()}).safeParse(req.params);if(!p.success)return reply.code(400).send({error:'Invalid sector pack id'});const row=db.prepare("SELECT * FROM rule_packs WHERE id=? AND sector='hospital' AND status='draft'").get(p.data.id) as any;if(!row)return reply.code(404).send({error:'Hospital draft pack not found'});db.prepare("UPDATE rule_packs SET status='approved' WHERE id=?").run(row.id);setSetting('sector','hospital');setSetting('packVersion',row.version);addLedger('sector-pack-approved',String(row.id),row.version);return {ok:true,sector:'hospital',version:row.version,status:'Approved by demo human action; legal rules remain unverified.'}});
function ledgerVerify(){const rows=db.prepare('SELECT id,entity_type,entity_id,payload_hash,prev_hash,hash FROM ledger ORDER BY id').all() as any[];let prev='GENESIS';for(let i=0;i<rows.length;i++){const r=rows[i];const expected=createHash('sha256').update(prev+'|'+r.entity_type+'|'+r.entity_id+'|'+r.payload_hash).digest('hex');if(r.prev_hash!==prev||r.hash!==expected)return {valid:false,brokenIndex:i+1,checked:rows.length};prev=r.hash}return {valid:true,checked:rows.length,lastHash:prev,mode:'SHA-256 hash-chain verification'}}
app.get('/api/ledger/verify',async()=>ledgerVerify());
app.post('/api/ledger/tamper-test',async()=>{const row=db.prepare('SELECT id FROM ledger ORDER BY id DESC LIMIT 1').get() as any;if(!row)return {ok:false,message:'No ledger rows available'};db.prepare("UPDATE ledger SET payload_hash='tampered-demo-value' WHERE id=?").run(row.id);return {ok:true,verification:ledgerVerify(),message:'Demo-only tamper test changed one ledger payload hash.'}});
