app.post('/api/pay/check',async(req,reply)=>{const p=z.object({base:z.coerce.number().min(0).max(10000000),hours:z.coerce.number().min(0).max(500),rate:z.coerce.number().min(0).max(100000),paid:z.coerce.number().min(0).max(10000000),multiplier:z.coerce.number().min(1).max(5).default(2)}).safeParse(req.body);if(!p.success)return reply.code(400).send({error:'Invalid pay calculation inputs'});const standard=48;const overtime=Math.max(0,p.data.hours-standard);const overtimeAmount=overtime*p.data.rate*p.data.multiplier;const expected=p.data.base+overtimeAmount;return {hoursWorked:p.data.hours,standardHours:standard,overtimeHours:overtime,overtimeAmount,expectedGross:expected,paid:p.data.paid,delta:expected-p.data.paid,explanation:[`${p.data.hours} hours worked`,`${overtime} hours above the illustrative 48-hour weekly threshold`,`Overtime estimate = ${overtime} × ₹${p.data.rate} × ${p.data.multiplier}`,`Expected gross ₹${expected}; recorded paid ₹${p.data.paid}`],rulePack:setting('packVersion','demo-v0.1'),verified:false,disclaimer:'Illustrative calculation only. Confirm the applicable official rule pack.'}});
app.post('/api/disputes',async(req,reply)=>{const p=z.object({reason:z.string().min(3).max(1000),payslipId:z.number().int().positive().optional()}).safeParse(req.body);if(!p.success)return reply.code(400).send({error:'Enter a short reason'});const r=db.prepare('INSERT INTO disputes(worker_id,payslip_id,reason,status,created_at) VALUES(?,?,?,?,?)').run('W-101',p.data.payslipId||null,clean(p.data.reason),'Open',now());addLedger('dispute',String(r.lastInsertRowid),p.data.reason);return {ok:true,id:Number(r.lastInsertRowid),status:'Open',message:'Dispute saved. Human review is required.'}});
