app.post('/api/reset',async()=>{db.exec('DELETE FROM receipts;DELETE FROM reports;DELETE FROM ledger;DELETE FROM tickets;DELETE FROM cases;DELETE FROM disputes;DELETE FROM feedback;DELETE FROM notices;DELETE FROM swaps;DELETE FROM sos_events;DELETE FROM payslips;DELETE FROM certifications;DELETE FROM contractors;DELETE FROM skills;DELETE FROM rule_packs;DELETE FROM agent_runs;DELETE FROM used_nonces;DELETE FROM device_keys;DELETE FROM roster_proposals;DELETE FROM worker_confirmations;');const stamp=(m:number)=>new Date(Date.now()-m*60000).toISOString();const ins=db.prepare('INSERT INTO receipts(worker_id,site_id,type,method,created_at,signature_status) VALUES(?,?,?,?,?,?)');for(let i=0;i<18;i++)ins.run('W-'+String(101+i).padStart(3,'0'),'SITE-CON-B',i%2===0?'in':'out',i%3===0?'manual':'qr',stamp(i*31+4),i%3===0?'Simulated · flagged':'Simulated · signed');const samples:any[]=[['Wet floor',4,'Block B','Water pooled beside the stairwell','Open',12],['Wet floor',4,'Block B','Slippery water near the stairs','Seen',1484],['Electrical hazard',5,'Workshop','Exposed cable near the workbench','Open',65],['Heat exposure',3,'Outdoor zone','Workers need additional shade and water','In progress',130],['Equipment',2,'Gate','A barrier is difficult to move','Open',190],['Wet floor',4,'Block B','The floor is still slippery by the entry','Open',3130],['PPE concern',3,'Workshop','Protective gloves are running low','Resolved',400]];const ri=db.prepare('INSERT INTO reports(site_id,category,severity,zone,summary,status,pseudonym,created_at) VALUES(?,?,?,?,?,?,?,?)');for(const r of samples)ri.run('SITE-CON-B',r[0],r[1],r[2],r[3],r[4],createHmac('sha256',process.env.SERVER_SECRET||'fairshift-demo-only').update(randomUUID()).digest('hex'),stamp(r[5]));for(const r of db.prepare('SELECT id,category,summary FROM reports').all() as any[])addLedger('report',String(r.id),JSON.stringify(r));for(const r of db.prepare('SELECT id,type,created_at FROM receipts').all() as any[])addLedger('receipt',String(r.id),JSON.stringify(r));const pay=db.prepare('INSERT INTO payslips(worker_id,period,base,overtime_hours,overtime_amount,deductions,paid_amount,created_at) VALUES(?,?,?,?,?,?,?,?)');pay.run('W-101','October 2026',16000,6,2400,0,17200,now());pay.run('W-102','October 2026',15000,4,1600,300,16300,now());db.prepare('INSERT INTO contractors(name,worker_group,amount_due,amount_paid,due_date,paid_date) VALUES(?,?,?,?,?,?)').run('Metro Works Partner','Site crew · 12 workers',96000,72000,new Date(Date.now()-9*86400000).toISOString().slice(0,10),null);db.prepare('INSERT INTO certifications(worker_id,name,expires_at,status) VALUES(?,?,?,?)').run('W-104','Working at Heights',new Date(Date.now()+10*86400000).toISOString().slice(0,10),'Expiring soon');db.prepare('INSERT INTO certifications(worker_id,name,expires_at,status) VALUES(?,?,?,?)').run('W-108','First Aid Basics',new Date(Date.now()+45*86400000).toISOString().slice(0,10),'Active');db.prepare('INSERT INTO skills(worker_id,name,issuer,issued_at,signature) VALUES(?,?,?,?,?)').run('W-101','Workplace Safety Induction','Sunrise Builders Demo Training',now(),createHash('sha256').update('Workplace Safety Induction|Sunrise Builders Demo Training|fairshift-demo').digest('hex'));setSetting('sector','construction');setSetting('packVersion','construction-v0.1');return {ok:true,message:'Synthetic demo data reset to the baseline state'}});

app.get('/api/pay/worker/:workerId',async(req,reply)=>{const p=z.object({workerId:z.string().min(2).max(50)}).safeParse(req.params);if(!p.success)return reply.code(400).send({error:'Invalid worker id'});const slips=db.prepare('SELECT * FROM payslips WHERE worker_id=? ORDER BY id DESC').all(p.data.workerId) as any[];return {workerId:p.data.workerId,payslips:slips.map(s=>({id:s.id,period:s.period,base:s.base,overtimeHours:s.overtime_hours,overtimeAmount:s.overtime_amount,deductions:s.deductions,expectedNet:s.base+s.overtime_amount-s.deductions,paidAmount:s.paid_amount,delta:s.base+s.overtime_amount-s.deductions-s.paid_amount,rulePack:setting('packVersion','demo-v0.1'),verified:false})),disclaimer:'Illustrative synthetic data; not legal advice.'}});
app.post('/api/pay/check-week',async(req,reply)=>{const p=z.object({hoursByDay:z.array(z.coerce.number().min(0).max(24)).length(7),hourlyRate:z.coerce.number().min(0).max(100000),base:z.coerce.number().min(0).max(10000000).default(0),paid:z.coerce.number().min(0).max(10000000),dailyStandard:z.coerce.number().min(1).max(24).default(8),weeklyStandard:z.coerce.number().min(1).max(168).default(48),multiplier:z.coerce.number().min(1).max(5).default(2)}).safeParse(req.body);if(!p.success)return reply.code(400).send({error:'Provide seven daily hour values and valid pay details.'});const calc=computeOvertimeAmount(p.data.hoursByDay,p.data.hourlyRate,p.data.multiplier,p.data.dailyStandard,p.data.weeklyStandard);const expected=p.data.base+calc.overtimeAmount;return {...calc,base:p.data.base,expectedGross:expected,paid:p.data.paid,delta:Number((expected-p.data.paid).toFixed(2)),rulePack:setting('packVersion','demo-v0.1'),verified:false,explanation:[`Daily hours: ${p.data.hoursByDay.join(', ')}`,`Daily overtime total: ${calc.dailyOvertimeHours} hours`,`Weekly overtime total: ${calc.weeklyOvertimeHours} hours`,`Combined overtime (no double-count): ${calc.overtimeHours} hours`,`Overtime amount = ${calc.overtimeHours} × ₹${p.data.hourlyRate} × ${p.data.multiplier}`],disclaimer:'Demo computation only. Apply only after human verification of an official rule pack.'}});
app.get('/api/fatigue/:workerId',async(req,reply)=>{const p=z.object({workerId:z.string().min(2).max(50)}).safeParse(req.params);if(!p.success)return reply.code(400).send({error:'Invalid worker id'});const receipts=db.prepare("SELECT type,created_at FROM receipts WHERE worker_id=? AND created_at>=datetime('now','-8 days') ORDER BY created_at").all(p.data.workerId) as any[];const intervals=computeWorkedIntervals(receipts);const hoursLast24h=intervals.intervals.filter(i=>new Date(i.end).getTime()>Date.now()-86400000).reduce((a,i)=>a+i.hours,0);const hoursLast7d=intervals.totalHours;const result=fatigueScore({hoursLast24h,hoursLast7d,restGapHours:11,consecutiveDays:Math.min(7,Math.ceil(hoursLast7d/8)),nightShiftStreak:0,heatExposure:0});return {...result,workerId:p.data.workerId,inputs:{hoursLast24h:Number(hoursLast24h.toFixed(1)),hoursLast7d,restGapHours:11,consecutiveDays:Math.min(7,Math.ceil(hoursLast7d/8)),nightShiftStreak:0,heatExposure:0},mode:'Rule-based estimate',disclaimer:'Decision support only; not a medical assessment. Inputs are estimated from available demo receipts.'}});
app.get('/api/ledger/export.csv',async(_req,reply)=>{const rows=db.prepare('SELECT id,entity_type,entity_id,payload_hash,prev_hash,hash,created_at FROM ledger ORDER BY id').all() as any[];const csv=['id,entity_type,entity_id,payload_hash,prev_hash,hash,created_at',...rows.map(r=>Object.values(r).map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(','))].join('\n');reply.header('content-type','text/csv; charset=utf-8').header('content-disposition','attachment; filename="fairshift-ledger-demo.csv"');return csv});
app.get('/api/cases',async()=>db.prepare('SELECT id,site_id,category,summary,severity,report_count,distinct_reporters,status,created_at FROM cases ORDER BY id DESC').all());
app.patch('/api/cases/:id/status',async(req,reply)=>{const p=z.object({id:z.coerce.number().int().positive()}).safeParse(req.params);const b=z.object({status:z.enum(['Open','Investigating','Resolved'])}).safeParse(req.body);if(!p.success||!b.success)return reply.code(400).send({error:'Invalid case update'});const result=db.prepare('UPDATE cases SET status=? WHERE id=?').run(b.data.status,p.data.id);if(!result.changes)return reply.code(404).send({error:'Case not found'});addLedger('case-status',String(p.data.id),b.data.status);return {ok:true,id:p.data.id,status:b.data.status}});
app.get('/api/roster/proposals',async()=>db.prepare('SELECT * FROM roster_proposals ORDER BY id DESC').all());
app.post('/api/roster/proposals/:id/apply',async(req,reply)=>{const p=z.object({id:z.coerce.number().int().positive()}).safeParse(req.params);if(!p.success)return reply.code(400).send({error:'Invalid proposal id'});const r=db.prepare("UPDATE roster_proposals SET status='Applied as proposal' WHERE id=?").run(p.data.id);if(!r.changes)return reply.code(404).send({error:'Proposal not found'});addLedger('roster-proposal',String(p.data.id),'Applied as proposal; schedules not automatically changed');return {ok:true,status:'Applied as proposal',message:'Proposal recorded for human review. Worker notifications are not connected in this demo.'}});
app.post('/api/sector-pack/generate',async(req,reply)=>{const p=z.object({prompt:z.string().min(10).max(2000)}).safeParse(req.body);if(!p.success)return reply.code(400).send({error:'Describe the sector pack you need.'});const hospital={id:'hospital-draft-v1',sector:'hospital',version:'hospital-draft-v1',asOf:now().slice(0,10),verified:false,dailyStandard:8,weeklyStandard:48,overtimeMultiplier:2,minRestHours:11,maxConsecutiveDays:6,source:'Generated mock pack from user prompt',kind:'demo',roles:['Nursing','Sanitation','Security','Facilities'],hazards:['Wet floor','Biological safety','Needlestick','Equipment','Fatigue','Harassment'],prompt:p.data.prompt,needsHumanReview:true};const validation=RulePackSchema.safeParse({id:hospital.id,sector:hospital.sector,version:hospital.version,asOf:hospital.asOf,verified:hospital.verified,dailyStandard:hospital.dailyStandard,weeklyStandard:hospital.weeklyStandard,overtimeMultiplier:hospital.overtimeMultiplier,minRestHours:hospital.minRestHours,maxConsecutiveDays:hospital.maxConsecutiveDays,source:hospital.source,kind:hospital.kind});if(!validation.success)return reply.code(500).send({error:'Generated pack failed schema validation'});const r=db.prepare('INSERT INTO rule_packs(sector,version,status,verified,as_of,json,source,created_at) VALUES(?,?,?,?,?,?,?,?)').run('hospital',hospital.version,'draft',0,hospital.asOf,JSON.stringify(hospital),hospital.source,now());addLedger('sector-pack-draft',String(r.lastInsertRowid),JSON.stringify(hospital));return {ok:true,id:Number(r.lastInsertRowid),pack:hospital,status:'Draft — human review required',simulated:true}});

app.get('/api/disputes/:id/pdf',async(req,reply)=>{const p=z.object({id:z.coerce.number().int().positive()}).safeParse(req.params);if(!p.success)return reply.code(400).send({error:'Invalid dispute id'});const d=db.prepare('SELECT * FROM disputes WHERE id=?').get(p.data.id) as any;if(!d)return reply.code(404).send({error:'Dispute not found'});const slip=d.payslip_id?db.prepare('SELECT * FROM payslips WHERE id=?').get(d.payslip_id) as any:null;const pdf=textPdf('FairShift Dispute Pack',[`Dispute ID: ${d.id}`,`Worker reference: ${d.worker_id}`,`Status: ${d.status}`,`Created: ${d.created_at}`,`Reason: ${d.reason}`,`Resolution: ${d.resolution||'Pending human review'}`,...(slip?[`Payslip period: ${slip.period}`,`Base: ${slip.base}`,`Overtime amount: ${slip.overtime_amount}`,`Deductions: ${slip.deductions}`,`Paid amount: ${slip.paid_amount}`]:[]),`Active rule pack: ${setting('packVersion','demo-v0.1')}`,`Rule pack verified: no`,`Ledger integrity: ${JSON.stringify(ledgerVerify())}`,'Decision support only. Not legal advice. Synthetic demo record.']);reply.header('content-type','application/pdf').header('content-disposition',`attachment; filename="fairshift-dispute-${d.id}.pdf"`);return reply.send(pdf)});
app.get('/api/export/inspection.pdf',async(_req,reply)=>{const rows=db.prepare('SELECT worker_id,type,method,created_at,hash FROM receipts ORDER BY id DESC LIMIT 100').all() as any[];const pdf=textPdf('FairShift Inspection Export',[`Generated: ${now()}`,`Active sector: ${setting('sector','construction')}`,`Rule pack: ${setting('packVersion','demo-v0.1')} (unverified)`,`Receipt rows included: ${rows.length}`,...rows.map(r=>`${r.worker_id} | ${r.type} | ${r.method} | ${r.created_at} | ${String(r.hash||'').slice(0,24)}`),`Ledger check: ${JSON.stringify(ledgerVerify())}`,'Synthetic demo data. Not an official register or legal compliance certificate.']);reply.header('content-type','application/pdf').header('content-disposition','attachment; filename="fairshift-inspection-demo.pdf"');return reply.send(pdf)});
app.get('/api/export/impact.pdf',async(_req,reply)=>{const reportCount=(db.prepare('SELECT COUNT(*) n FROM reports').get() as any).n;const caseCount=(db.prepare('SELECT COUNT(*) n FROM cases').get() as any).n;const skillCount=(db.prepare('SELECT COUNT(*) n FROM skills').get() as any).n;const resolved=(db.prepare("SELECT COUNT(*) n FROM reports WHERE status='Resolved'").get() as any).n;const pdf=textPdf('FairShift SDG 8 Impact Report',[`Generated: ${now()}`,'SDG 8.5 - Decent work and equal pay: pay transparency checks are illustrative; no real recovery is measured.',`SDG 8.8 - Safe working environments: ${reportCount} synthetic hazard reports; ${resolved} marked resolved; ${caseCount} collective cases.`,`Skills and employability: ${skillCount} demo skill records.`,`Sector: ${setting('sector','construction')}`,`Active pack: ${setting('packVersion','demo-v0.1')} (unverified)`,`Ledger verification: ${JSON.stringify(ledgerVerify())}`,'All figures are synthetic demo data, not measured real-world impact.']);reply.header('content-type','application/pdf').header('content-disposition','attachment; filename="fairshift-sdg8-impact-demo.pdf"');return reply.send(pdf)});
app.post('/api/demo/scenario/:id',async(req,reply)=>{const p=z.object({id:z.enum(['S1','S2','S3','S4','S5','S6','S7','S8','S9'])}).safeParse(req.params);if(!p.success)return reply.code(400).send({error:'Scenario must be S1–S9'});const id=p.data.id;let result:any={scenario:id,ok:true,mode:'synthetic deterministic demo'};
 if(id==='S1'){const slip=db.prepare("SELECT * FROM payslips WHERE worker_id='W-101' ORDER BY id DESC LIMIT 1").get() as any;const d=db.prepare('INSERT INTO disputes(worker_id,payslip_id,reason,status,created_at) VALUES(?,?,?,?,?)').run('W-101',slip?.id||null,'Scenario S1: seeded overtime underpayment requires review','Open',now());addLedger('scenario-dispute',String(d.lastInsertRowid),'S1 underpayment dispute');result={...result,disputeId:Number(d.lastInsertRowid),status:'Open',pdfUrl:`/api/disputes/${Number(d.lastInsertRowid)}/pdf`}}
 if(id==='S2'){const rows=db.prepare("SELECT id,category,zone,summary,pseudonym,created_at FROM reports WHERE site_id=? AND category='Wet floor' AND created_at>=datetime('now','-14 days')").all(site()) as any[];const distinct=new Set(rows.map(r=>r.pseudonym));const days=new Set(rows.map(r=>String(r.created_at).slice(0,10)));let caseId:any=null;if(distinct.size>=3&&days.size>=2){const existing=db.prepare("SELECT id FROM cases WHERE site_id=? AND category='Wet floor' AND status!='Resolved' LIMIT 1").get(site()) as any;if(existing)caseId=existing.id;else{const c=db.prepare('INSERT INTO cases(site_id,category,summary,severity,report_count,distinct_reporters,status,created_at) VALUES(?,?,?,?,?,?,?,?)').run(site(),'Wet floor','Collective case: repeated wet-floor reports across multiple shifts',5,rows.length,distinct.size,'Open',now());caseId=Number(c.lastInsertRowid)}for(const r of rows)db.prepare('UPDATE reports SET cluster_id=? WHERE id=?').run(caseId,r.id);addLedger('scenario-collective-case',String(caseId),JSON.stringify({reports:rows.length,reporters:distinct.size,days:days.size}))}result={...result,unresolvedWetFloorReports:rows.length,distinctReporters:distinct.size,distinctDays:days.size,caseId,collectiveCases:(db.prepare('SELECT COUNT(*) n FROM cases').get() as any).n,message:caseId?'Collective Case promoted from seeded synthetic reports.':'Seeded reports do not meet the distinct reporter/day threshold yet.'}}
 if(id==='S3'){result={...result,forecast:(await app.inject({method:'GET',url:'/api/forecast'})).json(),rosterProposal:(await app.inject({method:'POST',url:'/api/roster/optimise'})).json()}}
 if(id==='S4'){const r=db.prepare("SELECT id FROM reports WHERE severity>=4 AND status!='Resolved' ORDER BY id LIMIT 1").get() as any;result={...result,ticketId:r?.id||null,escalation:'Simulated: no background scheduler is active; ticket can be reviewed in admin queue.'}}
 if(id==='S5'){result={...result,message:'Use /api/ledger/tamper-test to deliberately mutate a ledger row in demo mode.'}}
 if(id==='S6'){result={...result,message:'Use POST /api/sector-pack/generate with a hospital staffing prompt to create a draft; human approval is required.'}}
 if(id==='S7'){result={...result,watcher:(await app.inject({method:'POST',url:'/api/rule-watcher/check'})).json()}}
 if(id==='S8'){const r=db.prepare('INSERT INTO sos_events(site_id,worker_id,zone,status,created_at) VALUES(?,?,?,?,?)').run(site(),'W-101','Scenario S8 zone','Active',now());addLedger('scenario-sos',String(r.lastInsertRowid),'S8');result={...result,sosId:Number(r.lastInsertRowid),status:'Active',notification:'Simulated'}}
 if(id==='S9'){result={...result,briefing:(await app.inject({method:'GET',url:'/api/briefing'})).json()}}
 return result;
});
